INSERT INTO places (id,name,category,district,history,highlight,address,art,source,image) VALUES ('bangsaen','หาดบางแสน','ทะเลและเกาะ','เมืองชลบุรี','ชายหาดที่อยู่คู่เมืองชลบุรีมานาน เป็นจุดพักผ่อนริมทะเลและพื้นที่ท่องเที่ยวสำคัญของชุมชนแสนสุข','เดินเล่นริมชายหาด ชมทะเล และรับประทานอาหารในย่านบางแสน','ตำบลแสนสุข อำเภอเมืองชลบุรี จังหวัดชลบุรี','wave','https://thai.tourismthailand.org/Destinations/Provinces/chon-buri/464','');
INSERT INTO places (id,name,category,district,history,highlight,address,art,source,image) VALUES ('kohlarn','เกาะล้าน','ทะเลและเกาะ','บางละมุง','เกาะนอกชายฝั่งพัทยา มีชายหาดหลายแห่งและชุมชนท้องถิ่นที่รองรับการท่องเที่ยวทางทะเล','พักผ่อนริมชายหาด สำรวจเกาะ และชมทัศนียภาพทะเล','เกาะล้าน เมืองพัทยา อำเภอบางละมุง จังหวัดชลบุรี','island','https://thai.tourismthailand.org/Destinations/Provinces/chon-buri/464','');
INSERT INTO places (id,name,category,district,history,highlight,address,art,source,image) VALUES ('sichang','เกาะสีชัง','วัฒนธรรม','เกาะสีชัง','เกาะที่มีความเกี่ยวข้องกับประวัติศาสตร์ราชสำนัก มีพระจุฑาธุชราชฐานและสะพานอัษฎางค์เป็นจุดน่าสนใจ','เรียนรู้ประวัติศาสตร์ เดินชมชุมชน และชมวิวชายฝั่ง','อำเภอเกาะสีชัง จังหวัดชลบุรี','island','https://thai.tourismthailand.org/Destinations/Provinces/chon-buri/464','');
INSERT INTO places (id,name,category,district,history,highlight,address,art,source,image) VALUES ('nongnooch','สวนนงนุช','นันทนาการ','สัตหีบ','แหล่งท่องเที่ยวที่รวบรวมสวนจัดภูมิทัศน์และพื้นที่พักผ่อน เป็นหนึ่งในสถานที่ท่องเที่ยวที่ ททท. แนะนำในจังหวัดชลบุรี','ชมสวนและถ่ายภาพภูมิทัศน์หลากหลายรูปแบบ','ตำบลนาจอมเทียน อำเภอสัตหีบ จังหวัดชลบุรี','garden','https://thai.tourismthailand.org/Destinations/Provinces/chon-buri/464','');
INSERT INTO places (id,name,category,district,history,highlight,address,art,source,image) VALUES ('khaokheow','สวนสัตว์เปิดเขาเขียว','นันทนาการ','ศรีราชา','แหล่งเรียนรู้เกี่ยวกับสัตว์และธรรมชาติในพื้นที่อำเภอศรีราชา ซึ่งเป็นแหล่งท่องเที่ยวสำคัญของจังหวัด','เรียนรู้เรื่องสัตว์และการอนุรักษ์ เหมาะกับการท่องเที่ยวกับครอบครัว','ตำบลบางพระ อำเภอศรีราชา จังหวัดชลบุรี','garden','https://thai.tourismthailand.org/Destinations/Provinces/chon-buri/464','');
INSERT INTO places (id,name,category,district,history,highlight,address,art,source,image) VALUES ('ang-sila','ตลาดเก่าอ่างศิลา','ชุมชนและตลาด','เมืองชลบุรี','ย่านชุมชนเก่าริมทะเลที่สะท้อนวิถีชีวิตของคนอ่างศิลา และเป็นแหล่งท่องเที่ยวชุมชนที่ ททท. แนะนำ','เดินสำรวจชุมชน เลือกซื้อผลิตภัณฑ์ท้องถิ่น และสัมผัสบรรยากาศตลาด','ตำบลอ่างศิลา อำเภอเมืองชลบุรี จังหวัดชลบุรี','town','https://thai.tourismthailand.org/Destinations/Provinces/chon-buri/464','');
INSERT INTO places (id,name,category,district,history,highlight,address,art,source,image) VALUES ('sammuk','เขาสามมุข','ธรรมชาติ','เมืองชลบุรี','ภูเขาริมทะเลใกล้บางแสน มีศาลเจ้าแม่เขาสามมุขและทัศนียภาพชายฝั่ง เป็นจุดท่องเที่ยวที่รู้จักกันมานาน','ชมวิวชายฝั่งและแวะสักการะศาลเจ้าแม่เขาสามมุข','ตำบลแสนสุข อำเภอเมืองชลบุรี จังหวัดชลบุรี','island','https://thai.tourismthailand.org/Destinations/Provinces/chon-buri/464','');
INSERT INTO places (id,name,category,district,history,highlight,address,art,source,image) VALUES ('nongmon','ตลาดหนองมน','ชุมชนและตลาด','เมืองชลบุรี','ตลาดของฝากที่เป็นที่รู้จักในจังหวัดชลบุรี มีอาหารและผลิตภัณฑ์ท้องถิ่นให้เลือกซื้อ','เลือกซื้อข้าวหลาม อาหาร และของฝากจากชุมชน','ตำบลแสนสุข อำเภอเมืองชลบุรี จังหวัดชลบุรี','town','https://thai.tourismthailand.org/Destinations/Provinces/chon-buri/464','');
